from django.conf import settings


def stop_orders_of_discharged_stays(apps, schema_editor):
    """
    Final E2E audit (A1): discharge did not stop the stay's ward medication
    orders, so a discharged patient's later doses kept showing as due. New
    discharges stop them; this stops the ones already left active, ending each
    on its stay's discharge day. Recorded and scheduled doses stay as history.
    """
    MAR = apps.get_model("nurses", "MAR")
    zone = ZoneInfo(getattr(settings, "HOSPITAL_TIME_ZONE", "Asia/Kolkata"))
    for order in MAR.objects.filter(is_active=True, admission__status="Discharged").select_related("admission"):
        left = order.admission.discharge_date
        end = left.astimezone(zone).date() if left else order.end_date
        if order.end_date is not None and end is not None and order.end_date < end:
            end = order.end_date
        MAR.objects.filter(pk=order.pk).update(is_active=False, end_date=end)


